type Scan { value: Int, next: Int }

fn char_at(cs: List[Str], pos: Int) -> Str {
  return cs.get_or(pos, "")
}

fn digit_value(c: Str) -> Int {
  if c.is_empty() {
    return -1
  }
  return "0123456789".index_of(c).unwrap_or(-1)
}

fn read_int(cs: List[Str], pos: Int, acc: Int) -> Scan {
  let d = digit_value(char_at(cs, pos))
  if d >= 0 {
    return read_int(cs, pos + 1, acc * 10 + d)
  }
  return Scan { value: acc, next: pos }
}

fn unit_index(c: Str) -> Int {
  if c.is_empty() {
    return -1
  }
  return "dhms".index_of(c).unwrap_or(-1)
}

fn unit_seconds(u: Int) -> Int {
  let table: List[Int] = [86400, 3600, 60, 1]
  return table.get_or(u, 0)
}

fn parse_parts(cs: List[Str], pos: Int, min_unit: Int, total: Int) -> Result[Int, Str] {
  if pos == cs.len() {
    return Ok(total)
  }
  let scan = read_int(cs, pos, 0)
  if scan.next == pos {
    return Err("invalid duration")
  }
  let u = unit_index(char_at(cs, scan.next))
  if u < 0 or u <= min_unit {
    return Err("invalid duration")
  }
  let add = scan.value * unit_seconds(u)
  return parse_parts(cs: cs, pos: scan.next + 1, min_unit: u, total: total + add)
}

pub fn duration(s: Str) -> Result[Int, Str] {
  let cs = s.chars()
  if cs.is_empty() {
    return Err("invalid duration")
  }
  return parse_parts(cs: cs, pos: 0, min_unit: -1, total: 0)
}
